<script>
  // ─── HAMBURGER MENU ────────────────────────────────────────
  const menuBtn = document.getElementById('menuBtn');
  const mobileDrawer = document.getElementById('mobileDrawer');

  menuBtn.addEventListener('click', () => {
    const isOpen = menuBtn.classList.toggle('open');
    mobileDrawer.classList.toggle('open', isOpen);
    menuBtn.setAttribute('aria-expanded', String(isOpen));
    menuBtn.setAttribute('aria-label', isOpen ? 'Close navigation menu' : 'Open navigation menu');
    document.body.style.overflow = isOpen ? 'hidden' : '';
  });

  // Close drawer when clicking outside
  document.addEventListener('click', (e) => {
    if (mobileDrawer.classList.contains('open') &&
        !mobileDrawer.contains(e.target) &&
        !menuBtn.contains(e.target)) {
      menuBtn.classList.remove('open');
      mobileDrawer.classList.remove('open');
      menuBtn.setAttribute('aria-expanded', 'false');
      menuBtn.setAttribute('aria-label', 'Open navigation menu');
      document.body.style.overflow = '';
    }
  });

  // Close drawer on ESC
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && mobileDrawer.classList.contains('open')) {
      menuBtn.classList.remove('open');
      mobileDrawer.classList.remove('open');
      menuBtn.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
      menuBtn.focus();
    }
  });

  // ─── AUTOCOMPLETE ──────────────────────────────────────────
  const searchInput = document.getElementById('searchInput');
  const dropdown = document.getElementById('autocompleteList');
  const allItems = dropdown.querySelectorAll('.dropdown-item');

  const suggestions = [
    { title: 'Primary Care', sub: 'General health & preventive care', type: 'specialty' },
    { title: 'Dentist', sub: 'Cleanings, fillings, and oral health', type: 'specialty' },
    { title: 'Dermatologist', sub: 'Skin conditions & cosmetic consultations', type: 'specialty' },
    { title: 'Psychiatrist', sub: 'Mental health evaluations & medication management', type: 'specialty' },
    { title: 'Eye Doctor', sub: 'Vision exams & glasses prescriptions', type: 'specialty' },
    { title: 'Orthopedic Surgeon', sub: 'Joint pain, fractures & sports injuries', type: 'specialty' },
    { title: 'Back pain', sub: 'Orthopedic · Physiatry · Primary Care', type: 'condition' },
    { title: 'Anxiety', sub: 'Psychiatry · Psychology · Primary Care', type: 'condition' },
    { title: 'Acne', sub: 'Dermatology · Primary Care', type: 'condition' },
    { title: 'Dr. Sarah Chen', sub: 'Primary Care · 4.9 ★ · New York, NY', type: 'provider' },
    { title: 'Dr. Michael Ross', sub: 'Orthopedic · 4.8 ★ · Chicago, IL', type: 'provider' },
  ];

  searchInput.addEventListener('focus', () => {
    if (searchInput.value.trim() === '') {
      dropdown.classList.add('visible');
    }
  });

  searchInput.addEventListener('input', () => {
    const val = searchInput.value.toLowerCase().trim();
    if (val === '') {
      // Show default suggestions
      allItems.forEach(item => item.style.display = '');
      dropdown.classList.add('visible');
      return;
    }

    const filtered = suggestions.filter(s =>
      s.title.toLowerCase().includes(val) || s.sub.toLowerCase().includes(val)
    );

    // Hide/show items based on match
    allItems.forEach(item => {
      const title = item.querySelector('.dropdown-item-title')?.textContent || '';
      const matches = suggestions.some(s =>
        s.title === title && (s.title.toLowerCase().includes(val) || s.sub.toLowerCase().includes(val))
      );
      item.style.display = matches ? '' : 'none';
    });

    const hasVisible = [...allItems].some(i => i.style.display !== 'none');
    dropdown.classList.toggle('visible', hasVisible);
  });

  // Select from dropdown
  allItems.forEach(item => {
    item.addEventListener('click', () => {
      const val = item.getAttribute('data-value') ||
                  item.querySelector('.dropdown-item-title')?.textContent || '';
      searchInput.value = val;
      dropdown.classList.remove('visible');
      searchInput.focus();
    });

    item.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        item.click();
      }
    });
  });

  // Close dropdown on outside click
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.search-field')) {
      dropdown.classList.remove('visible');
    }
  });

  // ─── SEARCH HINT TAGS ──────────────────────────────────────
  document.querySelectorAll('.search-hint-tag').forEach(tag => {
    tag.addEventListener('click', () => {
      searchInput.value = tag.dataset.fill || tag.textContent.trim();
      searchInput.dispatchEvent(new Event('input'));
      searchInput.focus();
    });
  });

  // ─── INSURANCE SELECT STYLE ────────────────────────────────
  const insuranceSelect = document.getElementById('insuranceSelect');
  insuranceSelect.addEventListener('change', () => {
    insuranceSelect.classList.toggle('has-value', insuranceSelect.value !== '');
  });

  // ─── SEARCH BUTTON ─────────────────────────────────────────
  document.querySelector('.search-btn').addEventListener('click', () => {
    const q = searchInput.value.trim();
    const loc = document.getElementById('locationInput').value.trim();
    if (!q) {
      searchInput.focus();
      searchInput.style.outline = '2px solid #FF4D4D';
      setTimeout(() => searchInput.style.outline = '', 1500);
      return;
    }
    // In a real app this would navigate to results; demo alert
    alert(`Searching for "${q}"${loc ? ` near "${loc}"` : ''}…`);
  });

  // ─── SPECIALTY CARDS ───────────────────────────────────────
  document.querySelectorAll('.specialty-card').forEach(card => {
    card.addEventListener('click', (e) => {
      e.preventDefault();
      const name = card.querySelector('.specialty-name')?.textContent || '';
      // In production, navigate to ?specialty=...
      searchInput.value = name;
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setTimeout(() => searchInput.focus(), 600);
    });
  });

  // ─── SCROLL FADE-IN ────────────────────────────────────────
  const fadeEls = document.querySelectorAll('.fade-up');

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry, i) => {
      if (entry.isIntersecting) {
        const delay = entry.target.closest('.specialty-grid, .steps-grid, .testimonials-grid, .stats-inner')
          ? [...entry.target.parentElement.children].indexOf(entry.target) * 80
          : 0;
        setTimeout(() => entry.target.classList.add('visible'), delay);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

  fadeEls.forEach(el => observer.observe(el));
</script>

